package au.aumanet.app;
import android.content.Context;import org.json.*;import java.io.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;

/** Actual export policy + native verified-image preparation. MediaStore itself is a declared fake sink. */
public final class GroupImageExportTest{
 static final AtomicInteger checks=new AtomicInteger();static int tests;static Path root;static final String PROCESS="12345678-1234-1234-1234-123456789abc",GROUP="a".repeat(32),SELF="AA".repeat(32),SENDER="BB".repeat(32),ID="c".repeat(32),NAME="AuMaNET-20261112-012345abcdef.jpg";
 static void check(boolean value,String why){checks.incrementAndGet();if(!value)throw new AssertionError(why);}interface Work{void run()throws Exception;}static Exception rejects(Work work,String why)throws Exception{try{work.run();}catch(Exception refused){checks.incrementAndGet();return refused;}throw new AssertionError(why);}
 static GroupImageExport.Source source(byte[] bytes,AtomicBoolean current)throws Exception{return new GroupImageExport.Source(PROCESS,new GroupTextStore.Scope(GROUP,SELF),SENDER,ID,GroupTextWire.hash(bytes),bytes,current::get);}
 static final class Sink implements GroupImageExport.Store,GroupImageExport.Pending{
  final ByteArrayOutputStream bytes=new ByteArrayOutputStream();final List<String> events=new ArrayList<>();String fail="";boolean published,deleted;int inserts,deletes;Runnable onWrite=()->{},onPublish=()->{};
  public GroupImageExport.Pending insert(String name)throws Exception{inserts++;events.add("insert-pending");if(fail.equals("insert"))throw new IOException("PRIVATE_PROVIDER_PATH");if(fail.equals("null-insert"))return null;return this;}
  public OutputStream open()throws Exception{events.add("open");if(fail.equals("open"))throw new IOException("PRIVATE_PROVIDER_PATH");if(fail.equals("null-open"))return null;return new OutputStream(){public void write(int value)throws IOException{bytes.write(value);}public void write(byte[] b,int off,int len)throws IOException{events.add("write");bytes.write(b,off,len);onWrite.run();if(fail.equals("write"))throw new IOException("PRIVATE_PROVIDER_PATH");}public void flush()throws IOException{events.add("flush");if(fail.equals("flush"))throw new IOException("PRIVATE_PROVIDER_PATH");}public void close()throws IOException{events.add("close");if(fail.equals("close"))throw new IOException("PRIVATE_PROVIDER_PATH");}};}
  public boolean publish()throws Exception{events.add("publish");if(!fail.equals("zero-publish"))published=true;onPublish.run();if(fail.equals("publish"))throw new IOException("PRIVATE_PROVIDER_PATH");return !fail.equals("zero-publish");}
  public boolean delete()throws Exception{deletes++;events.add("delete-own");if(fail.equals("delete"))throw new IOException("PRIVATE_PROVIDER_PATH");deleted=true;published=false;return true;}
 }
 static void transaction()throws Exception{
  tests++;byte[] bytes=GroupImageLimitsTest.padded(GroupImageLimitsTest.jpeg(32,32,.65f,13),GroupTextWire.MAX_IMAGE);AtomicBoolean current=new AtomicBoolean(true);GroupImageExport.Source source=source(bytes,current);Sink sink=new Sink();JSONObject saved=GroupImageExport.save(source,sink,NAME);
  check(saved.getBoolean("saved")&&saved.getString("collection").equals("pictures")&&saved.getString("displayName").equals(NAME),"safe success fields");check(!saved.has("uri")&&!saved.has("path")&&!saved.has("dataBase64"),"no raw URI/path/image returned");check(sink.published&&!sink.deleted&&sink.inserts==1,"one pending copy published");check(Arrays.equals(bytes,sink.bytes.toByteArray()),"exact1MiB verified bytes copied without EXIF additions");check(sink.events.indexOf("close")<sink.events.indexOf("publish"),"publish follows closed complete writer");
  byte[] mutable=bytes.clone();GroupImageExport.Source frozen=source(mutable,current);mutable[20]^=1;Sink copy=new Sink();GroupImageExport.save(frozen,copy,NAME);check(Arrays.equals(copy.bytes.toByteArray(),bytes),"export retains immutable verified snapshot");
  current.set(false);Sink stopped=new Sink();rejects(()->GroupImageExport.save(source,stopped,NAME),"stale scope rejected");check(stopped.inserts==0,"no gallery insertion for stale scope");current.set(true);
  rejects(()->GroupImageExport.save(source,new Sink(),"../private.jpg"),"untrusted filename denied");rejects(()->new GroupImageExport.Source(PROCESS,new GroupTextStore.Scope(GROUP,SELF),SENDER,ID,"D".repeat(64),bytes,()->true),"hash mismatch denied");rejects(()->source(new byte[GroupTextWire.MAX_IMAGE+1],current),"oversize export denied");
 }
 static void failures()throws Exception{
  tests++;byte[] bytes=GroupImageLimitsTest.jpeg(256,256,.65f,14);AtomicBoolean current=new AtomicBoolean(true);GroupImageExport.Source source=source(bytes,current);
  for(String fault:new String[]{"insert","null-insert","open","null-open","write","flush","close","publish","zero-publish"}){Sink sink=new Sink();sink.fail=fault;Exception failed=rejects(()->GroupImageExport.save(source,sink,NAME),"provider failure must not report saved");check(!failed.getMessage().contains("PRIVATE_PROVIDER_PATH"),"safe fixed error only");check(!sink.published,"no visible partial or unconfirmed saved copy remains");check(sink.deletes==(fault.equals("insert")||fault.equals("null-insert")?0:1),"cleanup affects exact owned pending handle only");check(((GroupImageExport.SaveException)failed).uncertain==(fault.equals("insert")||fault.equals("null-insert")),"unknown insertion versus confirmed cleanup distinguished");}
  Sink lostScope=new Sink();lostScope.onWrite=()->current.set(false);rejects(()->GroupImageExport.save(source,lostScope,NAME),"scope lost during copy");check(lostScope.deleted&&!lostScope.events.contains("publish"),"scope loss deletes pending before publication");
  current.set(true);Sink lateScope=new Sink();lateScope.onPublish=()->current.set(false);rejects(()->GroupImageExport.save(source,lateScope,NAME),"scope lost during publication");check(lateScope.deleted&&!lateScope.published,"late scope loss deletes this exact copy");
  current.set(true);Sink cannotDelete=new Sink();cannotDelete.fail="delete";cannotDelete.onWrite=()->current.set(false);GroupImageExport.SaveException uncertain=(GroupImageExport.SaveException)rejects(()->GroupImageExport.save(source,cannotDelete,NAME),"cleanup failure stays uncertain");check(uncertain.uncertain&&uncertain.getMessage().equals(GroupImageExport.UNCONFIRMED),"check gallery guidance on unknown outcome");
 }
 static JSONObject ask(GroupMessages messages,GroupMessages.Action action)throws Exception{CompletableFuture<JSONObject> result=new CompletableFuture<>();messages.submit(action,new GroupMessages.Reply(){public void resolve(JSONObject value){result.complete(value);}public void reject(Exception error){result.completeExceptionally(error);}});return result.get(5,TimeUnit.SECONDS);}
 static final class Result implements GroupImageExport.Reply{final CompletableFuture<JSONObject> value=new CompletableFuture<>();final AtomicInteger calls=new AtomicInteger();public void saved(JSONObject saved){check(calls.incrementAndGet()==1,"one export callback");value.complete(saved);}public void failed(GroupImageExport.SaveException error){check(calls.incrementAndGet()==1,"one export callback");value.completeExceptionally(error);}}
 // Coordination bound, not an export latency SLA: cold Windows JVM/provider startup can exceed 3s.
 static void boundedJobs()throws Exception{
  tests++;byte[] bytes=GroupImageLimitsTest.jpeg(32,32,.65f,16);AtomicBoolean active=new AtomicBoolean(true),queuedAllowed=new AtomicBoolean(true);GroupImageExport.Source source=source(bytes,active);CountDownLatch started=new CountDownLatch(1),release=new CountDownLatch(1);Sink blocked=new Sink();blocked.onWrite=()->{started.countDown();try{if(!release.await(15,TimeUnit.SECONDS))throw new IllegalStateException("test barrier timeout");}catch(InterruptedException stopped){throw new IllegalStateException(stopped);}};
  Result first=new Result(),stale=new Result(),third=new Result(),overflow=new Result();Sink staleSink=new Sink(),thirdSink=new Sink(),overflowSink=new Sink();GroupImageExport.submit(source,blocked,first);check(started.await(15,TimeUnit.SECONDS),"one worker enters provider");GroupImageExport.submit(source(bytes,queuedAllowed),staleSink,stale);GroupImageExport.submit(source,thirdSink,third);GroupImageExport.submit(source,overflowSink,overflow);rejects(()->overflow.value.get(1,TimeUnit.SECONDS),"fourth task refused rather than adding an unbounded worker/queue");check(overflowSink.inserts==0,"rejected task creates no pending asset");queuedAllowed.set(false);release.countDown();first.value.get(3,TimeUnit.SECONDS);rejects(()->stale.value.get(3,TimeUnit.SECONDS),"queued scope loss denied");third.value.get(3,TimeUnit.SECONDS);check(staleSink.inserts==0&&blocked.published&&thirdSink.published,"retired queued work cannot publish and valid work completes");check(first.calls.get()==1&&stale.calls.get()==1&&third.calls.get()==1&&overflow.calls.get()==1,"no duplicate callbacks or automatic retry");
 }
 static void localOwnership(String aliceKey,String bobKey)throws Exception{
  tests++;GroupMessagesStoreTest.Identity alice=new GroupMessagesStoreTest.Identity(aliceKey),bob=new GroupMessagesStoreTest.Identity(bobKey);GroupSession session=new GroupSession();Set<String> approved=Set.of(alice.pin,bob.pin);Map<String,String> links=new HashMap<>();links.put(alice.pin,"live-source");session.set(new GroupTextAuthority.State(GROUP,bob.pin,alice.pin,1,1,true,approved,approved,links,approved));Context context=new Context(root.resolve("export-local-owner").toFile());GroupMessages messages=new GroupMessages(context,session,new GroupIdentity(bob));
  try{ask(messages,JSONObject::new);byte[] bytes=GroupImageLimitsTest.jpeg(64,64,.65f,15);GroupTextWire.Image image=new GroupTextWire.Image(64,64,bytes.length,GroupTextWire.hash(bytes),GroupTextWire.hash(bytes));long now=System.currentTimeMillis();GroupTextWire.Message incoming=new GroupTextWire.Message(GROUP,1,ID,alice.pin,List.of(bob.pin),now,now+GroupTextWire.TTL,"",2,false,image);messages.incoming(new GroupTextAuthority.Grant(session.state,alice.pin,()->true),GroupTextWire.sign(incoming,alice),false);ask(messages,JSONObject::new);new GroupImageFiles(context).put(session.state.scope,alice.pin,ID,bytes,image);
   String process=ask(messages,messages::snapshot).getString("processId");AtomicReference<GroupImageExport.Source> captured=new AtomicReference<>();ask(messages,()->{captured.set(messages.prepareImageExport(session.state.scope,alice.pin,ID,process,image.sha));return new JSONObject();});messages.pause();int networkFrames=session.frames.size();Sink sink=new Sink();GroupImageExport.save(captured.get(),sink,NAME);check(sink.published&&Arrays.equals(bytes,sink.bytes.toByteArray()),"explicit Save remains available after Stop/offline delivery");check(!messages.backgroundWorkNeeded()&&session.frames.size()==networkFrames,"save never re-arms transfer or emits network traffic");
   rejects(()->ask(messages,()->{messages.prepareImageExport(session.state.scope,alice.pin,ID,PROCESS,image.sha);return new JSONObject();}),"wrong source process rejected");rejects(()->ask(messages,()->{messages.prepareImageExport(session.state.scope,alice.pin,ID,process,"A".repeat(64));return new JSONObject();}),"wrong reviewed SHA rejected");
   session.set(new GroupTextAuthority.State("d".repeat(32),bob.pin,alice.pin,1,2,false,approved,approved,Map.of(),approved));Sink otherGroup=new Sink();rejects(()->GroupImageExport.save(captured.get(),otherGroup,NAME),"old scope cannot publish into replacement");check(otherGroup.inserts==0,"new group did not get old gallery copy");
  }finally{messages.shutdown();}
 }
 public static void main(String[] args)throws Exception{root=Paths.get(args[0]);GroupMessagesStoreTest.root=root;transaction();failures();boundedJobs();localOwnership(args[1],args[2]);System.out.println(new JSONObject().put("status","pass").put("testCount",tests).put("assertionCount",checks.get()).put("mediaStoreBoundary","Pending provider is a declared fake; actual API29+ MediaStore and permission behavior require Android acceptance"));}
}
